#!/usr/bin/env python3\n\"\"\"Simple Security Scanner for MLOps Bot.\"\"\"\n\nimport os\nimport re\nimport sys\nfrom pathlib import Path\nfrom datetime import datetime\n\ndef scan_for_security_issues(project_root):\n    \"\"\"Scan project for basic security issues.\"\"\"\n    \n    print(\"\\n🔍 TERRAGON AUTONOMOUS SDLC - SECURITY SCAN\")\n    print(\"=\" * 60)\n    \n    vulnerabilities = []\n    files_scanned = 0\n    \n    # Security patterns to check\n    security_patterns = {\n        'code_injection': [\n            (r'eval\\s*\\(', 'Use of eval() can lead to code injection', 'HIGH'),\n            (r'exec\\s*\\(', 'Use of exec() can lead to code injection', 'HIGH'),\n        ],\n        'command_injection': [\n            (r'os\\.system\\s*\\(', 'os.system() vulnerable to command injection', 'HIGH'),\n            (r'subprocess.*shell\\s*=\\s*True', 'subprocess with shell=True', 'HIGH'),\n        ],\n        'credentials': [\n            (r'password\\s*=\\s*[\"\\'][^\"\\'\n]{4,}[\"\\']', 'Hardcoded password detected', 'HIGH'),\n            (r'secret\\s*=\\s*[\"\\'][^\"\\'\n]{10,}[\"\\']', 'Hardcoded secret detected', 'HIGH'),\n            (r'api_key\\s*=\\s*[\"\\'][^\"\\'\n]{10,}[\"\\']', 'Hardcoded API key detected', 'HIGH'),\n        ],\n        'crypto': [\n            (r'hashlib\\.md5\\s*\\(', 'MD5 is cryptographically broken', 'MEDIUM'),\n            (r'random\\.random\\s*\\(', 'random.random() not cryptographically secure', 'LOW'),\n        ],\n        'unsafe_deserialization': [\n            (r'pickle\\.loads?\\s*\\(', 'Pickle deserialization can be dangerous', 'HIGH'),\n            (r'yaml\\.load\\s*\\([^)]*(?!Loader\\s*=)', 'YAML load without SafeLoader', 'HIGH'),\n        ]\n    }\n    \n    # Scan Python files\n    for root, dirs, files in os.walk(project_root):\n        # Skip common ignore patterns\n        dirs[:] = [d for d in dirs if d not in {'.git', '__pycache__', 'venv', '.venv', 'node_modules'}]\n        \n        for file in files:\n            if file.endswith(('.py', '.yml', '.yaml', '.json')):\n                file_path = os.path.join(root, file)\n                rel_path = os.path.relpath(file_path, project_root)\n                \n                try:\n                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:\n                        content = f.read()\n                        lines = content.split('\\n')\n                        \n                        files_scanned += 1\n                        \n                        # Check each pattern category\n                        for category, patterns in security_patterns.items():\n                            for pattern, description, severity in patterns:\n                                for line_num, line in enumerate(lines, 1):\n                                    if re.search(pattern, line, re.IGNORECASE):\n                                        vulnerabilities.append({\n                                            'file': rel_path,\n                                            'line': line_num,\n                                            'category': category,\n                                            'description': description,\n                                            'severity': severity,\n                                            'code': line.strip(),\n                                            'pattern': pattern\n                                        })\n                \n                except Exception as e:\n                    print(f\"⚠️  Error scanning {rel_path}: {e}\")\n    \n    # Count vulnerabilities by severity\n    severity_counts = {'CRITICAL': 0, 'HIGH': 0, 'MEDIUM': 0, 'LOW': 0}\n    for vuln in vulnerabilities:\n        severity_counts[vuln['severity']] += 1\n    \n    # Print results\n    print(f\"\\n📊 SCAN RESULTS:\")\n    print(f\"  Files Scanned: {files_scanned}\")\n    print(f\"  Total Vulnerabilities: {len(vulnerabilities)}\")\n    print(f\"  🚨 Critical: {severity_counts['CRITICAL']}\")\n    print(f\"  ⚠️  High: {severity_counts['HIGH']}\")\n    print(f\"  🟡 Medium: {severity_counts['MEDIUM']}\")\n    print(f\"  🔵 Low: {severity_counts['LOW']}\")\n    \n    # Show vulnerabilities\n    if vulnerabilities:\n        print(f\"\\n🚨 VULNERABILITIES DETECTED:\")\n        \n        # Sort by severity\n        severity_order = {'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3}\n        vulnerabilities.sort(key=lambda x: (severity_order[x['severity']], x['file'], x['line']))\n        \n        for i, vuln in enumerate(vulnerabilities[:20], 1):  # Show first 20\n            severity_icon = {'CRITICAL': '🚨', 'HIGH': '⚠️', 'MEDIUM': '🟡', 'LOW': '🔵'}[vuln['severity']]\n            print(f\"  {i}. {severity_icon} {vuln['severity']} - {vuln['description']}\")\n            print(f\"     📁 {vuln['file']}:{vuln['line']}\")\n            print(f\"     💾 Code: {vuln['code'][:100]}{'...' if len(vuln['code']) > 100 else ''}\")\n            print()\n        \n        if len(vulnerabilities) > 20:\n            print(f\"  ... and {len(vulnerabilities) - 20} more vulnerabilities\")\n    \n    # Security recommendations\n    print(f\"\\n💡 SECURITY RECOMMENDATIONS:\")\n    \n    if severity_counts['CRITICAL'] > 0 or severity_counts['HIGH'] > 0:\n        print(\"  🚨 IMMEDIATE ACTION REQUIRED:\")\n        print(\"    - Address all critical and high severity vulnerabilities\")\n        print(\"    - Review code for security best practices\")\n        print(\"    - Implement security controls in CI/CD pipeline\")\n    \n    if len(vulnerabilities) > 0:\n        print(\"  🛡️  GENERAL SECURITY IMPROVEMENTS:\")\n        print(\"    - Use parameterized queries for database operations\")\n        print(\"    - Store secrets in environment variables\")\n        print(\"    - Use secure random number generators\")\n        print(\"    - Validate and sanitize all inputs\")\n        print(\"    - Regular security scanning and updates\")\n    else:\n        print(\"  ✅ No major security issues detected - good job!\")\n    \n    print(\"\\n\" + \"=\" * 60)\n    \n    # Security quality gate\n    critical_high = severity_counts['CRITICAL'] + severity_counts['HIGH']\n    \n    if critical_high > 0:\n        print(\"🚨 SECURITY QUALITY GATE: FAILED\")\n        print(f\"   Critical/High vulnerabilities must be fixed: {critical_high}\")\n        return 1\n    elif severity_counts['MEDIUM'] > 10:\n        print(\"⚠️  SECURITY QUALITY GATE: WARNING\")\n        print(f\"   Many medium-risk issues detected: {severity_counts['MEDIUM']}\")\n        return 0\n    else:\n        print(\"✅ SECURITY QUALITY GATE: PASSED\")\n        print(\"   Low security risk detected\")\n        return 0\n\ndef main():\n    \"\"\"Main function.\"\"\"\n    project_root = os.path.dirname(os.path.abspath(__file__))\n    \n    print(f\"\\n🔐 Starting security scan of: {project_root}\")\n    print(f\"⏰ Scan started at: {datetime.now()}\")\n    \n    exit_code = scan_for_security_issues(project_root)\n    \n    print(f\"\\n✅ Security scan completed\")\n    print(f\"📊 Exit code: {exit_code}\")\n    \n    return exit_code\n\nif __name__ == \"__main__\":\n    exit_code = main()\n    sys.exit(exit_code)\n